mockup.css:
.mock-hero-contact-sheet { background: #0b0b0a; color: #f4f1ea; font-family: "Inter", ui-sans-serif, sans-serif; }
.mock-hero-contact-sheet .tiles { position: absolute; inset: 0; display: grid;
  grid-template-columns: repeat(6, 1fr); grid-template-rows: repeat(4, 1fr); gap: .5cqw; padding: .5cqw; }
.mock-hero-contact-sheet .tiles i { display: block; filter: saturate(.55) contrast(1.05); }
.mock-hero-contact-sheet .veil { position: absolute; inset: 0; z-index: 2;
  background: linear-gradient(180deg, rgba(8,8,7,.35) 0%, rgba(8,8,7,.78) 55%, rgba(8,8,7,.92) 100%);
  display: flex; flex-direction: column; justify-content: flex-end; padding: 5cqw; gap: 2cqw; }
.mock-hero-contact-sheet h4 { margin: 0; font-size: 7.4cqw; line-height: .95; font-weight: 300; letter-spacing: -.02em; }
.mock-hero-contact-sheet .facts { display: flex; gap: 3cqw; font-size: 1.6cqw; letter-spacing: .1em;
  text-transform: uppercase; opacity: .72; }
